def clean(df):
    df = df.dropna(subset=['Region']).copy()
    df['Region'] = df['Region'].str.strip().str.title()
    df = df[df['Quantity'] > 0]
    return df

def answer(df):
    electronics_df = df[df['Category'] == 'Electronics']
    revenue_by_region = electronics_df.groupby('Region')['Revenue'].sum().to_dict()
    return revenue_by_region}
